// Staleness: one hash of everything the glue is made from (the config, the build options, the
// installed package versions), written into every generated file's header.

import { createHash } from "node:crypto";

/** The first line of every generated file's header: how `generate` tells its own files from
 *  the app's. */
export const GENERATED_MARK =
    "Generated by pureform: do not edit. Run `pureform generate` to update it.";

const HASH_LINE = /pureform-hash: ([0-9a-f]+)/;

/** JSON with object keys sorted, so equal values give equal text. Functions are kept as their
 *  source, `undefined` properties are left out, and a cycle is marked rather than followed. */
export const stableStringify = (value: unknown): string => {
    const ancestors = new Set<object>();
    const walk = (current: unknown): unknown => {
        if (typeof current === "function")
            return { $function: String(current) };
        if (typeof current === "bigint") return { $bigint: String(current) };
        if (typeof current === "symbol") return { $symbol: String(current) };
        if (current instanceof RegExp) return { $regexp: String(current) };
        if (current instanceof Date) return { $date: current.toISOString() };
        if (typeof current !== "object" || current === null) return current;
        if (ancestors.has(current)) return { $cycle: true };
        ancestors.add(current);
        let result: unknown;
        if (Array.isArray(current)) {
            result = current.map((item) => walk(item) ?? null);
        } else if (current instanceof Map) {
            result = { $map: walk([...current.entries()]) };
        } else if (current instanceof Set) {
            result = { $set: walk([...current.values()]) };
        } else {
            const sorted: Record<string, unknown> = {};
            for (const key of Object.keys(current).sort()) {
                const item = walk((current as Record<string, unknown>)[key]);
                if (item !== undefined) sorted[key] = item;
            }
            result = sorted;
        }
        ancestors.delete(current);
        return result;
    };
    return JSON.stringify(walk(value)) ?? "null";
};

/** A short hex hash of a value's stable JSON. */
export const hashOf = (value: unknown): string =>
    createHash("sha256")
        .update(stableStringify(value))
        .digest("hex")
        .slice(0, 16);

/** The header for a generated file, in its extension's comment syntax. */
export const header = (path: string, hash: string): string =>
    path.endsWith(".css")
        ? `/* ${GENERATED_MARK} */\n/* pureform-hash: ${hash} */\n`
        : `// ${GENERATED_MARK}\n// pureform-hash: ${hash}\n`;

/** A generated file's contents: the header, then the source. */
export const withHeader = (
    path: string,
    contents: string,
    hash: string,
): string => `${header(path, hash)}\n${contents}`;

/** Whether a file's contents start with the generated header. */
export const isGenerated = (contents: string): boolean =>
    contents.slice(0, 200).includes(GENERATED_MARK);

/** The hash in a generated file's header, or `undefined` when it has none. */
export const headerHash = (contents: string): string | undefined =>
    isGenerated(contents)
        ? HASH_LINE.exec(contents.slice(0, 300))?.[1]
        : undefined;
